<template>
  <section class="flex flex-col gap-10">
    <PageTitle title="Petition Page Details" />
    <div class="flex flex-col gap-4">
      <GoBackButton
        v-if="!isLoading && data"
        subject="petition details"
        :fallback-to="{ name: 'verification-ballots-id', params: { id: data.ballot_page.ballot_id } }"
      />
      <GoBackButton v-else subject="petitions list" :fallback-to="{ name: 'verification-ballots' }" />
      <AppLoader v-if="isLoading" subject="petition page details" />
      <AppError v-else-if="error" :error="error" title="Failed to load petition page details" />
      <AppEmpty v-else-if="!data" subject="petition page details" />
      <Card v-else>
        <CardContent class="flex flex-col gap-4">
          <div class="flex w-full justify-between items-center align-middle">
            <Button
              class="w-fit min-w-20"
              variant="outline"
              :disabled="!data.ballot_page.previous_page_id"
              @click="navigateToBallotPage(data.ballot_page.previous_page_id)"
              >Previous</Button
            >
            <span v-if="data.ballot_page.page_number !== null" class="text-xl justify-self-center align-middle"
              >Page # {{ data.ballot_page.page_number + 1 }}</span
            >
            <Button
              class="w-fit min-w-20"
              variant="outline"
              :disabled="!data.ballot_page.next_page_id"
              @click="navigateToBallotPage(data.ballot_page.next_page_id)"
              >Next</Button
            >
          </div>
          <div class="flex justify-between items-center gap-4 flex-wrap">
            <LabeledEntityDate label="Created At" :date="data.ballot_page.created_at" />
            <Badge :variant="getBallotPagesStatusBadge(data.ballot_page.state).variant">{{
              getBallotPagesStatusBadge(data.ballot_page.state).label
            }}</Badge>
          </div>
          <Separator />
          <BallotPagePreview
            :image-url="data.ballot_page.image_url"
            :data="data.submitted_signatures"
            :highlighted-signature-id="highlightedSignatureId"
          />
          <Separator />
          <BallotsSignaturesList
            :items="submittedSignatures"
            title="Submitted Signatures"
            :highlighted-signature-id="highlightedSignatureId"
            @signature-item-click="onSignatureItemClick"
          />
        </CardContent>
      </Card>
    </div>
  </section>
</template>

<script setup lang="ts">
import { useBallotPageDetails } from '~/queries/verification/ballots/pageDetails';
import { getBallotPagesStatusBadge } from '~/constants/verifications/ballotPagesStatus';

definePageMeta({
  roles: ['admin', 'manager'],
  backLabel: 'petition page',
});

useSeoMeta({
  title: 'Petition Page Details',
});

const { submittedSignatures, isLoading, error, data } = useBallotPageDetails();

async function navigateToBallotPage(id: string | null) {
  if (id) await navigateTo({ name: 'verification-ballots-pages-id', params: { id: id } });
}

const highlightedSignatureId = computed(() => useRoute().query.signature_id?.toString() || null);

function onSignatureItemClick(value: string) {
  const route = useRoute('verification-ballots-pages-id');
  const router = useRouter();
  router.replace({ query: route.query.signature_id?.toString() !== value ? { signature_id: value } : {} });
}
</script>
