import { getBallotVerificationPageDetails } from '~/client';
import type { GetBallotVerificationPageDetailsResponse } from '~/client';

export const useBallotPageDetails = defineQuery(() => {
  const route = useRoute('verification-ballots-pages-id');

  const pageId = computed(() => route.params.id);

  const { data, error, isLoading } = useQuery({
    key: () => ['ballot.page.details', pageId.value],
    query: () => getBallotVerificationPageDetails({ composable: '$fetch', path: { ballot_page_id: pageId.value } }),
    enabled: () => route.name === 'verification-ballots-pages-id',
  });

  return {
    submittedSignatures: computed(() => data.value?.submitted_signatures || []),
    data,
    error,
    isLoading,
  };
});
